rules.css:
@media (min-width: 1500px) {
  .map-hud { left: 18px; top: 18px; }
  .map-hud button { width: 40px; min-height: 40px; }
  .map-hud .hud-brand { font-size: 20px; min-width: 75px; }
}

@media (max-width: 1000px) {
  .toolbar-copy { display: none; }
  .business-toolbar { justify-content: space-between; }
  .business-header { gap: 12px; padding: 12px 18px; }
  .main-nav { gap: 0px; }
  .main-nav button { padding: 10px; }
  .business-brand small { display: none; }
  .business-brand { font-size: 20px; }
  .business-brand .brand-seal { width: 34px; height: 38px; font-size: 21px; }
  .header-actions { gap: 5px; }
  .header-actions button { padding: 8px 10px; }
  .overview-map { width: 190px; }
  .map-demo-marker .marker-detail { display: none; }
  .agent-layout { grid-template-columns: 1fr 1fr; }
  .quick-grid { grid-template-columns: repeat(2, minmax(0px, 1fr)); }
}

@media (max-width: 600px) {
  :root { --base-size: 15px; }
  .map-hud { top: max(10px,env(safe-area-inset-top)); left: 10px; right: 10px; justify-content: space-between; gap: 3px; padding: 6px; }
  .map-hud .hud-brand { font-size: 17px; min-width: 58px; }
  .map-hud button { width: 35px; min-height: 38px; flex: 0 0 auto; }
  .map-hud .hud-account { width: 30px; min-height: 30px; }
  .hud-account img { width: 30px; height: 30px; }
  .map-demo-marker { top: 72px; right: 14px; font-size: 10px; }
  .map-caption { bottom: 85px; left: 18px; }
  .map-caption > span { font-size: 14px; }
  .map-caption small { font-size: 11px; }
  .portrait-hint { display: inline-flex; bottom: max(24px,env(safe-area-inset-bottom)); }
  .return-hall { right: 14px; bottom: 82px; }
  .landmark { font-size: 14px; min-height: 40px; }
  .business-header { padding: 10px 12px; display: grid; grid-template-columns: 1fr auto; gap: 10px; }
  .business-brand { font-size: 20px; gap: 9px; }
  .main-nav { grid-area: 2 / 1 / auto / -1; width: 100%; justify-content: space-between; }
  .main-nav button { flex: 1 1 0%; min-height: 44px; font-size: 14px; padding: 8px; }
  .header-actions button { font-size: 13px; padding: 7px 10px; min-height: 40px; }
  .business-toolbar { padding: 7px 12px; gap: 8px; flex-wrap: wrap; }
  .toolbar-actions { gap: 5px; }
  .toolbar-actions button { font-size: 12px; padding: 6px 8px; }
  .toolbar-actions button[data-open="help"] { display: none; }
  .mode-tabs button { font-size: 12px; padding: 7px 9px; }
  #overview { padding: 24px 16px; }
  .overview-hero { padding-bottom: 24px; }
  .overview-hero h1 { font-size: 25px; }
  .overview-hero p { font-size: 14px; line-height: 1.8; }
  .overview-map { display: none; }
  .overview-hero .row { margin-top: 18px; }
  .list-heading { margin-top: 24px; }
  .list-heading h2 { font-size: 20px; }
  .tabs { gap: 2px; }
  .tabs button { font-size: 14px; padding: 10px 12px; }
  .task-row { display: grid; grid-template-columns: minmax(0px, 1fr) auto; gap: 10px; padding: 17px 0px; }
  .task-copy { display: contents; }
  .task-title { grid-column: 1 / -1; font-size: 16px; margin-bottom: 0px; }
  .task-meta { grid-area: 2 / 1; font-size: 12px; gap: 7px; }
  .task-actions { grid-area: 2 / 2; align-self: center; }
  .task-actions button { padding: 7px 10px; font-size: 13px; min-height: 44px; }
  .technical { grid-column: 1 / -1; font-size: 12px; margin-top: 0px; }
  dialog, dialog[data-panel] { width: 100vw; max-width: 100vw; max-height: 100dvh; height: 100dvh; min-height: 0px; margin: 0px; border: 0px; border-radius: 0px; box-shadow: none; }
  .panel-header { padding-right: 16px; padding-bottom: 14px; padding-left: 16px; padding-top: max(14px,env(safe-area-inset-top)); min-height: 74px; }
  .panel-kicker { font-size: 10px; }
  .panel-header h1 { font-size: 20px; }
  .panel-body { padding: 20px 16px; flex: 1 1 0%; }
  .panel-footer { padding-top: 13px; padding-right: 16px; padding-left: 16px; padding-bottom: max(13px,env(safe-area-inset-bottom)); gap: 8px; flex-wrap: wrap; }
  .panel-footer > .muted { display: none; }
  .panel-footer > .row { flex: 1 1 0%; gap: 8px; }
  .panel-footer button { font-size: 14px; padding: 10px 12px; min-height: 44px; }
  .panel-footer .primary { flex: 1 1 0%; }
  .panel-footer > .primary { margin-left: auto; }
  .field { margin-bottom: 19px; }
  .field-label { font-size: 14px; }
  textarea { min-height: 116px; }
  .steps { gap: 16px; margin-bottom: 22px; }
  .filter-row { gap: 12px; }
  .filter-row select { width: 100%; }
  .filter-row > .row { width: 100%; }
  .filter-row .row .primary { margin-left: auto; }
  .segmented { gap: 5px; }
  .segmented button { font-size: 12px; padding: 8px 10px; min-height: 40px; }
  .bounty-card { padding: 18px 0px; }
  .bounty-card h3 { font-size: 15px; }
  .bounty-card p { font-size: 14px; }
  .agent-layout { grid-template-columns: 1fr; gap: 16px; }
  .agent-row { padding: 11px; gap: 10px; }
  .agent-row .status { font-size: 11px; padding: 3px 6px; }
  .agent-detail { padding: 18px; }
  .agent-detail:empty { display: none; }
  .agent-info strong { font-size: 16px; }
  .agent-info small { font-size: 12px; }
  .file-grid { grid-template-columns: 1fr; }
  .file-card button { min-height: 40px; font-size: 13px; }
  .quick-grid { gap: 10px; }
  .quick-card { padding: 16px; min-height: 106px; }
  .definition { grid-template-columns: 76px minmax(0px, 1fr); gap: 12px; }
  .task-detail-title { flex-wrap: wrap; }
  .chat-toolbar { gap: 10px; }
  .chat-toolbar .row { gap: 4px; }
  .chat-toolbar .row button { padding: 7px 9px; font-size: 12px; }
  .chat-message { max-width: 100%; }
  .chat-bubble { font-size: 15px; padding: 10px 12px; }
  .chat-composer textarea { min-height: 72px; }
  .chat-composer .muted { font-size: 11px; }
  .chat-empty h2 { font-size: 22px; }
  .chat-empty .row { justify-content: center; }
  .setting-row { gap: 12px; align-items: flex-start; }
  .setting-row select { width: 140px; flex: 0 0 auto; }
  .setting-row small { font-size: 12px; }
  .reader { font-size: 15px; }
  .reader h2 { font-size: 23px; }
  .upload-block { padding: 12px; gap: 8px; }
  .upload-block button { white-space: nowrap; }
  .notification { padding: 13px; }
  .document-preview { padding: 20px; }
  .login-form { padding-top: 8px; }
}

@media (max-width: 360px) {
  .map-hud .hud-brand { font-size: 16px; min-width: 50px; }
  .map-hud button { width: 31px; }
  .map-hud .hud-account { width: 26px; }
  .hud-account img { width: 26px; height: 26px; }
  .toolbar-actions button { padding: 6px; }
  .header-actions button { padding: 7px 8px; }
  .task-meta { max-width: 150px; }
  .quick-card { padding: 13px; }
}

@media (max-height: 560px) and (orientation: landscape) {
  dialog, dialog[data-panel] { max-height: calc(-24px + 100dvh); height: auto; min-height: 0px; }
  .panel-header { padding: 10px 18px; }
  .panel-body { padding: 16px 20px; }
  .panel-footer { padding: 10px 20px; }
  .panel-kicker { display: none; }
  .map-caption { bottom: 16px; }
  .map-demo-marker { top: 20px; }
  .map-hud { top: 10px; right: auto; }
}

@media (max-width: 1200px) {
  #business-shell { grid-template-columns: 192px minmax(0px, 1fr); }
  .sidebar { padding-left: 10px; padding-right: 10px; }
  .work-brand { padding-left: 6px; gap: 9px; font-size: 21px; }
  .work-brand small { font-size: 11px; }
  .work-header { padding: 12px 26px; }
  #work-main { padding: 26px; }
  .work-footnote { padding-left: 26px; padding-right: 26px; }
  .start-steps { display: none; }
  .overview-columns { grid-template-columns: minmax(0px, 1fr) 264px; gap: 18px; }
  .recent-card { padding: 20px 18px 0px; }
  .section-head { gap: 8px; }
  .section-head p { font-size: 11px; }
  .attention-card, .compact-agents { padding: 18px; }
  .task-meta { gap: 6px; }
  .task-actions button { font-size: 11px; }
  .resource-strip { flex-wrap: wrap; }
  .work-header-actions { gap: 10px; }
  .breadcrumb { gap: 8px; }
}

@media (max-width: 1000px) {
  .overview-columns { grid-template-columns: minmax(0px, 1fr); }
  .overview-aside { grid-template-columns: repeat(2, minmax(0px, 1fr)); }
  .map-entry { grid-column: 1 / -1; height: 165px; }
  .attention-card { align-self: start; }
  .map-entry > img { object-position: center 43%; }
  .file-grid { grid-template-columns: minmax(0px, 1fr); }
  .agent-layout { grid-template-columns: minmax(0px, 1fr); }
  .breadcrumb > span, .breadcrumb > .var-icon--set { display: none; }
  .sidebar { padding-top: 22px; }
  .work-header { min-height: 68px; }
  .demo-badge { font-size: 10px; }
  #page-body { padding: 22px; }
}

@media (max-width: 760px) {
  #business-shell { display: block; }
  .sidebar { display: none; }
  .work-area { height: 100%; padding-bottom: calc(62px + env(safe-area-inset-bottom)); }
  .work-header { padding: 12px 20px; min-height: 64px; }
  .work-header-actions { gap: 8px; }
  .header-create { display: none; }
  .mobile-more { display: inline-flex !important; }
  .mobile-nav { position: absolute; bottom: 0px; left: 0px; right: 0px; height: calc(62px + env(safe-area-inset-bottom)); padding: 5px 12px max(5px,env(safe-area-inset-bottom)); border-top: 1px solid var(--line); background: var(--paper); z-index: 10; justify-content: space-between; display: flex !important; }
  .mobile-nav button { flex: 1 1 0%; min-height: 50px; display: flex; flex-direction: column; gap: 4px; border: 0px; color: var(--muted); font-size: 11px; padding: 5px; }
  .mobile-nav button.active { color: var(--brand); background: rgb(246, 238, 232); }
  .mobile-nav .var-icon--set { font-size: 21px; }
  #work-main { padding: 24px 20px; }
  .work-footnote { display: none; }
  .welcome h1 { font-size: 26px; }
  .start-card { padding: 22px; gap: 18px; }
  .start-mark { width: 50px; height: 64px; font-size: 30px; }
  .overview-columns { gap: 18px; }
  .page-heading h1 { font-size: 25px; }
  .page-heading { margin-bottom: 20px; }
  .page-heading p { font-size: 13px; }
  .page-heading .eyebrow { font-size: 11px; }
  #page-view[data-page="chat"] .page-surface { height: calc(100dvh - 264px - env(safe-area-inset-bottom)); min-height: 420px; }
  #page-footer { padding: 16px 20px; flex-wrap: wrap; }
  #page-footer > .muted { display: none; }
  .work-header .breadcrumb strong { font-size: 15px; }
  .toast { bottom: 82px; }
  dialog .toast { bottom: 18px; }
}

@media (max-width: 600px) {
  #work-main { padding: 22px 16px; }
  #overview { padding: 0px; }
  .work-header { padding: 10px 16px; }
  .work-header-actions { gap: 5px; }
  .demo-badge { font-size: 10px; }
  .welcome { margin-bottom: 20px; }
  .welcome .eyebrow { font-size: 10px; }
  .welcome h1 { font-size: 25px; letter-spacing: 0px; }
  .welcome p { font-size: 13px; line-height: 1.8; max-width: 280px; }
  .start-card { padding: 21px 18px; gap: 12px; margin-bottom: 20px; align-items: flex-start; }
  .start-mark { width: 34px; height: 43px; font-size: 23px; border-radius: 18px 18px 6px 6px; }
  .start-copy h2 { font-size: 16px; }
  .start-copy p { font-size: 12px; line-height: 1.8; }
  .start-copy .row { gap: 8px; }
  .start-copy button { padding: 9px 10px; min-height: 42px; font-size: 12px; }
  .start-copy .var-icon--set { font-size: 16px; }
  .overview-aside { grid-template-columns: minmax(0px, 1fr); gap: 18px; }
  .map-entry { height: 185px; }
  .recent-card { padding: 18px 16px 0px; }
  .section-head h2 { font-size: 15px; }
  .section-head button { font-size: 11px; }
  .section-head p { font-size: 11px; max-width: 170px; }
  .tabs { gap: 7px; }
  .tabs button { font-size: 12px; padding: 12px 5px; }
  .task-row { padding: 17px 0px; gap: 8px; }
  .task-title { font-size: 15px; font-weight: 500; }
  .task-meta { font-size: 11px; gap: 5px; }
  .task-meta .status { font-size: 11px; padding: 3px 6px; }
  .task-actions button { min-height: 42px; font-size: 11px; padding: 5px 0px 5px 5px; }
  .technical { font-size: 11px; }
  .task-actions { align-self: start; }
  .task-actions .var-icon--set { font-size: 14px; }
  .resource-strip { padding: 18px 16px; gap: 12px; }
  .resource-strip h3 { font-size: 13px; }
  .resource-strip p { font-size: 11px; }
  .resource-strip button { margin-left: auto; font-size: 12px; }
  .attention-card, .compact-agents { padding: 20px; }
  .attention-item strong, .compact-agent strong { font-size: 14px; }
  .attention-item small, .compact-agent em { font-size: 12px; }
  .compact-agent { padding: 12px 0px; }
  .compact-agent .portrait { width: 40px; height: 40px; }
  .side-note { font-size: 12px; }
  .map-entry strong { font-size: 16px; }
  .map-entry small { font-size: 12px; }
  #page-body { padding: 20px 16px; }
  #page-footer { padding: 14px 16px; }
  .page-heading p { line-height: 1.8; }
  dialog, dialog[data-panel] { width: 100vw; height: 100dvh; max-height: 100dvh; max-width: 100vw; border-radius: 0px; border: 0px; margin: 0px; }
  .panel-body { padding: 20px 16px; }
  .panel-header { padding-right: 16px; padding-bottom: 16px; padding-left: 16px; padding-top: max(16px,env(safe-area-inset-top)); }
  .panel-footer { padding-top: 14px; padding-right: 16px; padding-left: 16px; padding-bottom: max(14px,env(safe-area-inset-bottom)); }
  .panel-header h1 { font-size: 21px; }
  .panel-footer button { min-height: 44px; }
  .filter-row .row { width: 100%; }
  .filter-row select { width: 100%; }
  .board-list .task-row { padding: 20px 0px; }
  .board-list .task-title { font-size: 15px; }
  .board-list .task-meta { font-size: 11px; }
  .board-list .task-actions button { font-size: 11px; padding: 8px; }
  .file-card { padding: 18px; }
  .file-grid { grid-template-columns: minmax(0px, 1fr); }
  .quick-card { min-height: 95px; }
  .quick-card span { font-size: 14px; }
  .chat-composer .muted { font-size: 11px; }
  .chat-composer .row { gap: 6px; }
  .setting-row { gap: 12px; flex-wrap: wrap; }
  .setting-row select { width: 100%; }
  .setting-row:has(input[type="checkbox"]) { flex-wrap: nowrap; }
  .setting-row small { font-size: 12px; }
  .chat-toolbar { gap: 14px; }
  .chat-recipient { font-size: 12px; }
  .chat-empty { padding: 15px 0px; }
  .chat-empty h2 { font-size: 21px; }
  .chat-empty p { font-size: 13px; }
  .chat-empty .row button { font-size: 12px; }
  .chat-message .portrait { width: 28px; height: 28px; }
  .chat-bubble { font-size: 14px; }
  .chat-composer textarea { min-height: 78px; }
  #page-view[data-page="chat"] .page-surface { min-height: 490px; }
  .toast { font-size: 13px; padding: 10px 14px; }
  .large-type .side-nav button, .large-type .task-title { font-size: 17px; }
}

@media (max-width: 360px) {
  .demo-badge { display: none; }
  .start-card { padding: 18px 14px; }
  .start-mark { display: none; }
  .start-copy button { padding: 9px 12px; }
  .section-head { align-items: flex-start; gap: 5px; }
  .section-head p { max-width: 150px; }
  .section-head button { max-width: 88px; white-space: normal; text-align: right; }
  .task-meta { max-width: none; }
  .task-meta > span:last-child { max-width: 125px; }
  .task-actions button { font-size: 11px; }
  .recent-card { padding: 18px 12px 0px; }
  .tabs { gap: 4px; }
  .tabs button { font-size: 11px; }
  .chat-composer .row .muted { max-width: 160px; }
  .header-create { display: none; }
}

@media (max-height: 560px) and (orientation: landscape) {
  dialog, dialog[data-panel] { width: min(1000px, -32px + 100vw); height: auto; max-height: calc(-24px + 100dvh); min-height: 0px; margin: auto; border-radius: 10px; }
  .panel-header { padding: 10px 20px; }
  .panel-body { padding: 16px 20px; }
  .panel-footer { padding: 10px 20px; }
  .sidebar { padding-top: 14px; }
  .nav-caption { padding-top: 20px; }
  .sidebar-bottom { padding-top: 20px; }
  .work-header { min-height: 58px; }
  .work-footnote { display: none; }
}

@media (max-width: 600px) {
  .task-title { margin-bottom: 0px; }
  .task-row { row-gap: 9px; }
  .section-head p { max-width: none; }
  .section-head > div { min-width: 0px; }
  .section-head { align-items: center; }
  .section-head button { flex: 0 0 auto; }
  .task-meta { grid-area: 2 / 1; }
  .task-actions { grid-area: 2 / 2; align-self: center; }
}

@media (max-width: 600px) {
  .files-heading { display: grid; grid-template-columns: minmax(0px, 1fr); }
  .files-heading .intro { margin-bottom: 0px; }
  .files-heading > .primary { justify-self: start; margin-bottom: 14px; }
  .files-heading h2 { font-size: 18px; }
}

@media (max-width: 760px) {
  #business-shell[data-view="chat"] #work-main { padding: 0px; }
  #page-view[data-page="chat"] .page-surface { border: 0px; border-radius: 0px; }
  #page-view[data-page="chat"] #page-body { padding: 12px 16px 0px; }
  #page-view[data-page="chat"] #page-footer { padding: 10px 16px; }
  .chat-toolbar .row button { min-height: 40px; padding: 7px 8px; font-size: 12px; }
  .chat-toolbar .row .icon-button { padding: 0px; }
  .chat-composer textarea { font-size: 16px; resize: none; }
  .chat-composer button[type="submit"] { padding: 10px 13px; }
  .chat-empty { padding: 16px 0px; }
  .chat-empty h2 { font-size: 21px; }
}

@media (max-width: 600px) {
  dialog[data-panel="chat"] .panel-header { padding: max(10px, env(safe-area-inset-top)) 16px 10px; }
  dialog[data-panel="chat"] #panel-body { padding: 12px 16px 0px; }
  dialog[data-panel="chat"] .panel-footer { padding: 10px 16px max(10px, env(safe-area-inset-bottom)); }
}

@media (max-height: 560px) {
  #business-shell[data-view="chat"] #work-main { padding-top: 0px; padding-bottom: 0px; }
  #page-view[data-page="chat"] #page-body { padding-top: 6px; }
  #page-view[data-page="chat"] #page-footer { padding-top: 6px; padding-bottom: 6px; }
  .chat-sessions { margin-bottom: 4px; padding-bottom: 0px; }
  .chat-sessions button { min-height: 32px; padding-top: 5px; padding-bottom: 5px; }
  .chat-toolbar { padding-bottom: 4px; }
  .chat-empty { margin: 0px auto; padding: 8px 0px; }
  .chat-empty h2 { font-size: 18px; }
  .chat-empty p { margin: 6px 0px; }
  dialog[data-panel="chat"] { height: calc(-24px + 100dvh); }
  dialog[data-panel="chat"] .chat-recipient { display: none; }
  dialog[data-panel="chat"] .panel-header { padding-top: 6px; padding-bottom: 6px; }
  dialog[data-panel="chat"] #panel-body { padding-top: 6px; }
  dialog[data-panel="chat"] .panel-footer { padding-top: 6px; padding-bottom: 6px; }
}
